<main class="content"><section class="panel"><div class="panel-head"><div><h2>Usuarios y docentes</h2><p>Datos, roles, asignaturas y permisos.</p></div><button class="primary" data-open="user-modal">+ Agregar usuario</button></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Contacto</th><th>Rol</th><th>Asignatura</th><th>Permisos</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['first_name'].' '.$u['last_name'])?></b></td><td><?=e($u['email'])?><small><?=e($u['phone'])?></small></td><td><span class="tag"><?=e($u['role'])?></span></td><td><?=e($u['subject']??'—')?></td><td><?=$u['test_enabled']?'Test ✓':'Test —'?> · <?=$u['tabulator_enabled']?'Tab. ✓':'Tab. —'?></td><td><button type="button" class="edit" data-edit-user='<?=e(json_encode($u))?>'>Editar</button><form method="post" action="<?=url('/admin/usuarios/eliminar')?>" onsubmit="return confirm('¿Eliminar usuario?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="danger">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><dialog id="user-modal"><form method="post" action="<?=url('/admin/usuarios/guardar')?>" class="modal-form"><?=csrf_field()?><input type="hidden" name="id"><div class="modal-head"><h2>Usuario</h2><button type="button" data-close>×</button></div><div class="form-grid"><label>Nombre<input required name="first_name"></label><label>Apellido<input required name="last_name"></label><label>Correo<input required type="email" name="email"></label><label>Teléfono<input name="phone"></label><label>Rol<select required name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Asignatura<select name="subject_id"><option value="">Sin asignatura</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Contraseña<input type="password" name="password" placeholder="Vacía para conservar"></label><label class="check"><input type="checkbox" name="test_enabled" value="1"> Habilitar test</label><label class="check"><input type="checkbox" name="tabulator_enabled" value="1"> Habilitar tabulador</label><input type="hidden" name="active" value="1"></div><button class="primary">Guardar usuario</button></form></dialog></main>
